def items():
    out = []
    for n, (cl, area, par, mcqs, tf, shorts) in enumerate(I, 1):
        qs = [dict(type="mcq", text=t, options=list(o), answer=a) for t, o, a in mcqs]
        qs.append(dict(type="tf", text=tf[0], answer=tf[1]))
        qs += [dict(type="short", text=t, key=k, keywords=kw, rubric="Key idea: " + k) for t, k, kw in shorts]
        out.append(dict(paragraph=par, questions=qs, cluster=cl, area=area, words=len(par.split()), fk=None, approved=True, id=f"seed-{n:02d}"))
    return out
